
*{
    box-sizing:border-box
}
body{
    margin:0;
    background:#08152d;
    color:#f5f8ff;
    font-family:system-ui, 'Noto Sans Thai', sans-serif
}
button{
    font:inherit;
    cursor:pointer;
    border:0;
    border-radius:12px;
    padding:10px 14px;
    background:#f8c846;
    color:#132442;
    font-weight:800
}
button:disabled{
    opacity:.35;
    cursor:not-allowed
}
.app{
    max-width:1200px;
    margin:auto;
    padding:16px
}
header{
    display:flex;
    justify-content:space-between;
    align-items:center;
    gap:12px
}
h1{
    margin:0;
    color:#ffe08b;
    font-size:clamp(24px, 4vw, 40px)
}
h2{
    margin:8px 0 18px
}
.muted{
    color:#afc5e4
}
.panel{
    background:linear-gradient(135deg, #152c56, #101e3d);
    border:1px solid #406da6;
    border-radius:18px;
    padding:20px;
    margin:14px 0;
    box-shadow:0 10px 30px #0004
}
.grid{
    display:grid;
    grid-template-columns:repeat(auto-fit, minmax(170px, 1fr));
    gap:12px
}
.tile{
    border:2px solid #41669a;
    border-radius:14px;
    background:#102449;
    padding:14px;
    cursor:pointer;
    min-height:110px
}
.tile.sel{
    border-color:#ffd455;
    background:#214574
}
.tile:hover{
    border-color:#77c6ff
}
.tile strong{
    display:block;
    font-size:19px
}
.small{
    font-size:12px;
    color:#bdd3ee
}
.row{
    display:flex;
    gap:10px;
    align-items:center;
    flex-wrap:wrap
}
.space{
    justify-content:space-between
}
.hero{
    font-size:56px;
    margin:12px 0
}
.hidden{
    display:none!important
}
#game{
    width:100%;
    display:block;
    image-rendering:pixelated;
    border:2px solid #4e8bca;
    border-radius:14px;
    background:#83c5f7;
    touch-action:manipulation
}
.hud{
    display:grid;
    grid-template-columns:repeat(6, minmax(0, 1fr));
    gap:7px;
    margin-top:12px
}
.unitbtn{
    min-width:0;
    padding:8px 3px;
    background:#203f70;
    color:white;
    border:1px solid #74adf5
}
.unitbtn.ready{
    background:#214e70;
    border-color:#f9d96d
}
.unitbtn .face{
    font-size:27px;
    display:block
}
.unitbtn .cost{
    display:block;
    font-size:12px;
    color:#ffe18c
}
.stats{
    font-size:14px;
    color:#d9ebff
}
.meter{
    height:12px;
    border-radius:12px;
    background:#263c65;
    overflow:hidden
}
.meter>div{
    height:100%;
    background:linear-gradient(90deg, #ffbc35, #fff18b)
}
.status{
    padding:9px 0;
    font-size:14px
}
.secondary{
    background:#294d7d;
    color:white
}
.danger{
    background:#df5b6c;
    color:white
}
.footer{
    font-size:12px;
    color:#93afcd;
    margin-top:18px
}
@media(max-width:650px){
    .hud{
        grid-template-columns:repeat(3, 1fr)
    }
    .app{
        padding:8px
    }
    .panel{
        padding:12px
    }
    .tile{
        min-height:85px
    }
}
.stagewrap{
    position:relative;
    display:flex;
    gap:10px;
    align-items:flex-start
}
.stagecol{
    flex:1;
    min-width:0
}
.stats-panel{
    width:300px;
    flex:none;
    background:#0b1a38f2;
    border:1px solid #406da6;
    border-radius:16px;
    padding:12px;
    overflow:hidden;
    --tab:#f0743e;
    transition:width .25s ease, opacity .25s ease, padding .25s ease, margin .25s ease, transform .25s ease
}
.stats-panel.tab-def{
    --tab:#3b82f6
}
.stats-panel.tab-heal{
    --tab:#34d399
}
.stagewrap.closed .stats-panel{
    width:0;
    opacity:0;
    padding:0;
    border-width:0;
    margin-left:-10px;
    pointer-events:none
}
.stats-head{
    display:flex;
    justify-content:space-between;
    align-items:center;
    margin-bottom:8px;
    white-space:nowrap
}
.stats-x{
    padding:2px 9px;
    background:#294d7d;
    color:#fff;
    border-radius:8px
}
.stats-tabs{
    display:flex;
    gap:6px;
    margin-bottom:10px
}
.stats-tabs button{
    flex:1;
    padding:6px 4px;
    background:#203f70;
    color:#cfe3ff;
    border-radius:10px
}
#tab-dmg.active{
    background:#f0743e;
    color:#fff
}
#tab-def.active{
    background:#3b82f6;
    color:#fff
}
#tab-heal.active{
    background:#34d399;
    color:#06281c
}
#statsList{
    display:flex;
    flex-direction:column;
    gap:9px;
    min-width:270px
}
.shead{
    display:flex;
    justify-content:space-between;
    gap:8px
}
.sname{
    font-size:13px;
    font-weight:700
}
.sval{
    font-variant-numeric:tabular-nums;
    font-size:13px
}
.sbar{
    height:10px;
    background:#22375f;
    border-radius:8px;
    overflow:hidden
}
.sbar>div{
    height:100%;
    background:var(--tab);
    transition:width .3s ease
}
.stats-foot{
    margin-top:12px;
    font-size:13px;
    min-width:270px
}
.stats-edge{
    position:absolute;
    right:0;
    top:min(130px, 40%);
    z-index:6;
    padding:8px 7px;
    border-radius:10px 0 0 10px;
    font-size:16px;
    transition:right .25s ease
}
.stagewrap:not(.closed) .stats-edge{
    right:310px
}
@media(max-width:900px){
    .stats-panel{
        position:fixed;
        top:0;
        bottom:0;
        right:0;
        z-index:20;
        width:min(320px, 86%);
        border-radius:16px 0 0 16px;
        overflow-y:auto;
        box-shadow:0 8px 30px #000a
    }
    .stagewrap.closed .stats-panel{
        width:min(320px, 86%);
        padding:12px;
        border-width:1px;
        margin-left:0;
        transform:translateX(110%);
        visibility:hidden;
        transition:transform .25s ease, opacity .25s ease, visibility 0s .25s
    }
    .stats-edge{
        position:fixed;
        top:45%;
        z-index:21
    }
    .stagewrap:not(.closed) .stats-edge{
        right:min(320px, 86%)
    }
    #statsList, .stats-foot{
        min-width:0
    }
}

/* Landing screen: isolated styles, no changes to battle UI */
body:has(#home:not(.hidden)) { background:radial-gradient(ellipse at 50% 15%,#163b70 0%,#08152d 65%); }
body:has(#home:not(.hidden)) .app { min-height:100vh; display:flex; flex-direction:column; justify-content:center; max-width:1320px; padding:24px; }
body:has(#home:not(.hidden)) header { flex-direction:column; text-align:center; gap:7px; position:relative; z-index:1; }
body:has(#home:not(.hidden)) header h1 { font-size:clamp(35px,5.2vw,68px); letter-spacing:2px; line-height:1.1; text-shadow:0 4px 0 #a86626,0 10px 30px #0009; }
body:has(#home:not(.hidden)) header .muted { font-size:clamp(12px,1.5vw,16px); }
body:has(#home:not(.hidden)) #tag { border:1px solid #6c9ac9; background:#1a355c; border-radius:999px; padding:5px 17px; font-size:11px; letter-spacing:2px; margin-top:7px; }
#home { position:relative; isolation:isolate; overflow:hidden; text-align:center; padding:clamp(28px,4vw,48px) 20px 38px; border:1px solid #5485c3; border-radius:28px; background:radial-gradient(ellipse at 50% 28%,#28578d 0%,#172e57 52%,#0e1d3d 100%); box-shadow:0 25px 70px #0007,inset 0 1px #ffffff25; }
#home::before { content:''; position:absolute; inset:0; z-index:-1; opacity:.28; background-image:radial-gradient(#d5ebff 1px,transparent 1px); background-size:38px 38px; mask-image:linear-gradient(to bottom,#000,transparent 85%); }
#home::after { content:''; position:absolute; width:520px; height:520px; border-radius:50%; left:50%; top:5%; transform:translateX(-50%); z-index:-1; background:#5b9df0; filter:blur(110px); opacity:.14; pointer-events:none; }
#home .home-kicker { display:inline-block; padding:7px 15px; border-radius:999px; background:#1c4778; color:#9ee5ff; border:1px solid #487eaf; font-size:12px; font-weight:800; letter-spacing:2px; margin-bottom:15px; }
#home h2 { font-size:clamp(25px,3.2vw,41px); margin:0 0 12px; color:#fff0b9; text-shadow:0 3px 16px #0005; }
#home p { max-width:680px; margin:0 auto; line-height:1.8; color:#d5e6ff; font-size:clamp(14px,1.5vw,17px); }
#home .home-showdown { display:flex; justify-content:center; align-items:center; gap:clamp(10px,3vw,40px); margin:30px auto 26px; max-width:790px; }
#home .home-faction { flex:1; min-width:0; max-width:300px; padding:20px 12px 16px; border-radius:22px; border:1px solid #68bfff65; background:linear-gradient(155deg,#224d7b,#112849); box-shadow:inset 0 1px #ffffff22,0 12px 25px #0003; }
#home .home-faction.enemy { border-color:#ff9a9a65; background:linear-gradient(155deg,#62334e,#2a1d3a); }
#home .home-avatars { font-size:clamp(35px,5vw,61px); white-space:nowrap; letter-spacing:-8px; padding-right:8px; filter:drop-shadow(0 9px 8px #0005); animation:homeFloat 3.4s ease-in-out infinite; }
#home .enemy .home-avatars { animation-delay:-1.5s; }
#home .home-faction strong { display:block; margin-top:13px; font-size:clamp(13px,1.7vw,19px); }
#home .home-faction small { display:block; margin-top:5px; color:#a8c5e7; font-size:12px; }
#home .home-versus { color:#ffd465; font-weight:1000; font-size:clamp(23px,4vw,46px); font-style:italic; text-shadow:0 4px 20px #ffc64a77; }
#home .play-button { min-width:clamp(210px,27vw,300px); min-height:76px; padding:13px 35px; font-size:clamp(25px,3vw,32px); border-radius:19px; background:linear-gradient(180deg,#ffe995,#ffca43 65%,#f6ad22); color:#1a2943; border:2px solid #fff0b0; box-shadow:0 7px 0 #ad7119,0 16px 32px #0006,0 0 28px #ffc64b3b; transition:transform .14s ease,box-shadow .14s ease,filter .14s ease; }
#home .play-button:hover { transform:translateY(-4px) scale(1.03); filter:brightness(1.07); box-shadow:0 11px 0 #ad7119,0 20px 38px #0007,0 0 40px #ffc64b77; }
#home .play-button:active { transform:translateY(5px); box-shadow:0 2px 0 #ad7119,0 7px 18px #0006; }
#home .play-button:focus-visible { outline:3px solid #fff; outline-offset:5px; }
#home .home-cta-note { margin-top:20px; font-size:12px; color:#a9c5e6; letter-spacing:.4px; }
body:has(#home:not(.hidden)) .footer { text-align:center; line-height:1.7; }
@keyframes homeFloat { 0%,100% { transform:translateY(0); } 50% { transform:translateY(-8px); } }
@media(max-width:650px) { body:has(#home:not(.hidden)) .app { padding:14px 10px; } #home { padding:27px 12px 32px; } #home .home-showdown { gap:8px; } #home .home-faction { padding:15px 6px; } #home .home-avatars { letter-spacing:-7px; } #home .home-faction small { font-size:10px; } }
@media(prefers-reduced-motion:reduce) { #home .home-avatars { animation:none; } #home .play-button { transition:none; } }

/* Full-art main menu. Interactive hotspots align with the artwork's buttons. */
body:has(#home:not(.hidden)) { background:#07142b; }
body:has(#home:not(.hidden)) .app { max-width:none; padding:0; }
body:has(#home:not(.hidden)) header,
body:has(#home:not(.hidden)) .footer { display:none; }
#home.title-screen { position:relative; width:min(100vw,177.586vh); aspect-ratio:1648 / 928; margin:auto; padding:0; border:0; border-radius:0; box-shadow:none; overflow:hidden; background:#13254a; }
#home .title-art { width:100%; height:100%; display:block; object-fit:fill; }
#home .menu-hotspot { position:absolute; display:block; padding:0; border:0; border-radius:22px; background:transparent; color:transparent; font-size:0; cursor:pointer; touch-action:manipulation; }
#home .menu-hotspot.play { left:35%; top:70.2%; width:30%; height:15.2%; }
#home .menu-hotspot.characters { left:32.4%; top:87.8%; width:16.8%; height:9%; cursor:default; }
#home .menu-hotspot.settings { left:50.7%; top:87.8%; width:16.8%; height:9%; cursor:default; }
#home .menu-hotspot.play:hover { background:#fff3; box-shadow:0 0 25px #ffe26c99; }
#home .menu-hotspot.play:active { background:#fff5; transform:scale(.985); }
#home .menu-hotspot:focus-visible { outline:4px solid #fff; outline-offset:2px; }
@media(max-width:650px) { body:has(#home:not(.hidden)) .app { padding:0; } #home.title-screen { width:100vw; } }

/* Faculty selection: Base / Info / Select */
body:has(#faculty:not(.hidden)) .app {max-width:1600px;}
.faculty-screen {padding:clamp(16px,2.3vw,30px);}
.faculty-title {text-align:center;margin-bottom:22px;}
.faculty-title h2 {font-size:clamp(25px,3vw,38px);margin:5px 0 7px;color:#ffe18d;}
.faculty-title p {margin:0;}
.faculty-eyebrow {font-size:12px;font-weight:900;letter-spacing:3px;color:#7ac8ff;}
.faculty-layout {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;align-items:stretch;}
.faculty-column {height:620px;overflow:hidden;background:linear-gradient(160deg,#10254b,#0a1b38);border:1px solid #426da2;border-radius:18px;padding:18px;min-width:0;}
.faculty-column h3 {font-size:15px;letter-spacing:1.5px;color:#d5e9ff;margin:0 0 16px;padding-bottom:12px;border-bottom:1px solid #355780;}
.faculty-base {display:flex;flex-direction:column;}
.faculty-base-art {min-height:0;--faculty-color:#39c5ff;position:relative;min-height:0;flex:1;overflow:hidden;border-radius:15px;background:linear-gradient(#68b6f4 0%,#bce7ff 63%,#8cc69e 63%,#6eaa75 100%);border:2px solid #6ca9d7;isolation:isolate;}
.base-sun {position:absolute;top:32px;right:38px;width:66px;height:66px;background:#fff5c2;border-radius:50%;box-shadow:0 0 45px #fff8c0;}
.base-cloud {position:absolute;top:67px;left:18px;width:110px;height:27px;background:#ffffffb5;border-radius:50%;box-shadow:65px 23px 0 -6px #ffffff99;}
.base-building {position:absolute;width:68%;height:48%;bottom:16%;left:16%;border:5px solid #557092;border-radius:8px 8px 2px 2px;background:linear-gradient(90deg,#d5e8f3,#f5fbff 52%,#c8dbe8);box-shadow:10px 12px 0 #24415b4d;}
.base-roof {position:absolute;bottom:100%;left:-9%;width:118%;height:25px;background:var(--faculty-color);border:4px solid #355477;border-radius:8px 8px 2px 2px;box-shadow:0 -8px 0 -3px #eaf8ff;}
.base-emblem {position:absolute;top:9%;left:50%;transform:translateX(-50%);font-size:clamp(28px,4vw,48px);filter:drop-shadow(0 3px 2px #0003);}
.base-windows {position:absolute;top:49%;left:9%;right:9%;display:flex;justify-content:space-between;gap:5px;}
.base-windows i {width:18%;height:30px;background:#5e9bc8;border:3px solid #fff;}
.base-door {position:absolute;bottom:0;left:39%;width:22%;height:29%;background:#32577b;border:4px solid #a5c9e1;border-bottom:0;}
.base-ground {position:absolute;bottom:10%;left:-10%;width:120%;height:7%;background:#e6d7aa;border-top:5px solid #faf2d4;}
.base-name {text-align:center;margin-top:18px;font-weight:900;font-size:clamp(17px,2vw,23px);color:#ffe18d;}
.base-caption {text-align:center;margin-top:6px;}
.faculty-info-content {display:flex;flex-direction:column;gap:3px;min-height:0;overflow-y:auto;}
.info-faction {display:flex;gap:14px;align-items:center;background:#1b3965;padding:15px;border:1px solid #477ab2;border-radius:14px;margin-bottom:12px;}
.info-faction strong {display:block;font-size:clamp(17px,1.6vw,23px);margin:4px 0;overflow-wrap:anywhere;}
.info-big-icon {font-size:44px;}
.info-line {display:flex;justify-content:space-between;gap:12px;align-items:center;padding:13px 0;border-bottom:1px solid #29466c;font-size:13px;}
.info-line span {color:#b4cce9;}
.info-line strong {text-align:right;font-size:14px;overflow-wrap:anywhere;}
.info-hint {margin-top:18px;padding:14px;border-radius:12px;background:#1a3555;color:#c2daf5;font-size:13px;line-height:1.7;}
.faculty-select {display:flex;flex-direction:column;}
.faculty-select h3 {display:flex;justify-content:space-between;align-items:center;}
#facultySelectCount {font-size:11px;color:#91b6e3;letter-spacing:0;}
.faculty-options {display:flex;flex-direction:column;gap:8px;min-height:0;flex:1;overflow-y:auto;padding-right:4px;scrollbar-width:thin;scrollbar-color:#4e7cb2 transparent;}
.faculty-option {display:flex;align-items:center;text-align:left;gap:12px;width:100%;min-height:58px;padding:10px 12px;background:#162f57;color:#edf6ff;border:1px solid #42658e;border-radius:12px;font-weight:400;transition:background .12s,border-color .12s,transform .12s;}
.faculty-option:hover {background:#244777;border-color:#87c7ff;transform:translateX(-2px);}
.faculty-option.selected {background:#294e7b;border:2px solid #ffd45a;padding:9px 11px;}
.faculty-option-emoji {font-size:25px;flex:none;}
.faculty-option-text {min-width:0;flex:1;}
.faculty-option-text strong {display:block;font-size:14px;line-height:1.35;}
.faculty-option-text small {display:block;color:#a9c5e8;font-size:11px;margin-top:3px;}
.faculty-option-check {color:#ffd45a;font-size:20px;font-weight:900;}
.faculty-preview-note {text-align:center;color:#a8c5e6;font-size:12px;margin:13px 0 0;}
.faculty-actions {display:flex;justify-content:center;gap:14px;flex-wrap:wrap;margin-top:15px;}
.faculty-confirm {font-size:17px;padding:14px 26px;box-shadow:0 5px 0 #b58124;}
@media(max-width:1000px){.faculty-layout {grid-template-columns:1fr 1fr;}.faculty-column {height:560px;}.faculty-select {grid-column:1/-1;}.faculty-options {display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-content:start;}.faculty-base-art {min-height:300px;}}
@media(max-width:640px){.faculty-layout {grid-template-columns:1fr;}.faculty-column {height:500px;}.faculty-select {grid-column:auto;}.faculty-options {grid-template-columns:1fr;}.faculty-base-art {min-height:260px;}.faculty-column {padding:13px;}}

/* Faculty selection: illustrated campus theme */
body:has(#faculty:not(.hidden)) {
  background: #173b77;
}
body:has(#faculty:not(.hidden)) .app {
  max-width: none;
  min-height: 100vh;
  padding: 0;
}
body:has(#faculty:not(.hidden)) .app > header,
body:has(#faculty:not(.hidden)) .app > .footer { display: none; }
#faculty.faculty-screen {
  position: relative;
  isolation: isolate;
  min-height: 100vh;
  margin: 0;
  padding: clamp(18px, 2.6vw, 38px) clamp(16px, 3vw, 48px) 30px;
  border: 0;
  border-radius: 0;
  background: none;
  box-shadow: none;
}
#faculty.faculty-screen::before {
  content: '';
  position: fixed;
  inset: 0;
  z-index: -2;
  background: url("data:image/png;base64,") center center / cover no-repeat;
  pointer-events: none;
}
#faculty.faculty-screen::after {
  content: '';
  position: fixed;
  inset: 0;
  z-index: -1;
  background: linear-gradient(180deg, #062c7026 0%, #08285908 35%, #081d5340 100%);
  pointer-events: none;
}
#faculty .faculty-title { margin: 0 auto clamp(30px, 6vw, 85px); text-align: center; text-shadow: 0 2px 7px #081b4fe0; }
#faculty .faculty-eyebrow { color: white; font-size: 14px; letter-spacing: .4px; }
#faculty .faculty-title h2 { color: #fff; font-size: clamp(30px, 3.1vw, 48px); margin: 8px 0 9px; }
#faculty .faculty-title p { color: #fff; font-size: clamp(12px, 1.15vw, 16px); }
#faculty .faculty-layout { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; max-width: 1600px; margin: 0 auto; }
#faculty .faculty-column {
  height: clamp(510px, 60vh, 630px);
  padding: 18px;
  background: linear-gradient(155deg, #183e88ed, #102b6af0);
  border: 2px solid #6cbbff;
  border-radius: 21px;
  box-shadow: 0 6px 0 #061a4ec7, 0 16px 32px #061b4b65, inset 0 1px #ffffff30;
  backdrop-filter: blur(10px);
}
#faculty .faculty-column h3 { color: #ffd54d; font-size: 18px; letter-spacing: 0; border-bottom-color: #8fb6e440; }
#faculty .faculty-base-art { border-color: #5daff5; border-radius: 17px; }
#faculty .base-name { color: #fff; }
#faculty .base-caption { color: #d8e9ff; }
#faculty .info-faction { background: linear-gradient(135deg,#2c55a8,#1c377f); border: 1px solid #5c9bf4; border-left: 7px solid #35cbff; }
#faculty .info-line { border-bottom-color: #a9c9ff2b; }
#faculty .info-line span { color: #e2efff; }
#faculty .info-hint { background: #0b2056d9; border: 1px solid #294e9b; color: #e0edff; }
#faculty .faculty-option { background: linear-gradient(180deg,#2c53aa,#1c367e); border: 1px solid #6599ee; border-left: 7px solid var(--fo,#53d6bf); box-shadow: 0 4px 0 #08194b; }
#faculty .faculty-option:hover { background: #3b65b9; transform: translateY(-2px); }
#faculty .faculty-option.selected { border-color: #ffdc61; border-left-color: var(--fo,#53d6bf); background: #365fba; padding: 9px 11px; }
#faculty .faculty-preview-note { color: white; text-shadow: 0 2px 5px #06163c; margin-top: 23px; }
#faculty .faculty-actions { margin-top: 18px; }
#faculty .faculty-actions button { border: 1px solid #9ac9ff; box-shadow: 0 5px 0 #091d57, 0 9px 16px #091d5780; }
#faculty .faculty-actions .secondary { background: linear-gradient(#377be2,#1c51ad); }
#faculty .faculty-actions .faculty-confirm { background: linear-gradient(#ffe775,#ffbf16); border-color: #ffe88b; box-shadow: 0 5px 0 #9d6412,0 9px 16px #091d5780; }
@media(max-width:1000px) {
  #faculty .faculty-layout { grid-template-columns: repeat(2,minmax(0,1fr)); }
  #faculty .faculty-select { grid-column: 1/-1; }
  #faculty .faculty-column { height: 550px; }
  #faculty .faculty-title { margin-bottom: 35px; }
}
@media(max-width:640px) {
  #faculty.faculty-screen { padding: 22px 12px 30px; }
  #faculty .faculty-layout { grid-template-columns: 1fr; }
  #faculty .faculty-select { grid-column: auto; }
  #faculty .faculty-column { height: 480px; }
  #faculty .faculty-title { margin-bottom: 25px; }
}

/* Faculty screen: fit the viewport (including browser fullscreen/F11). */
@media (min-width: 1001px) and (min-height: 560px) {
  html:has(#faculty:not(.hidden)),
  body:has(#faculty:not(.hidden)) { width:100%; height:100%; overflow:hidden; overscroll-behavior:none; }
  body:has(#faculty:not(.hidden)) .app { height:100vh; height:100dvh; min-height:0; padding:0; overflow:hidden; }
  #faculty.faculty-screen { height:100vh; height:100dvh; min-height:0; padding:clamp(10px,1.8vh,22px) clamp(16px,2.6vw,44px); display:flex; flex-direction:column; overflow:hidden; }
  #faculty .faculty-title { flex:none; margin-bottom:clamp(12px,2vh,24px); }
  #faculty .faculty-title h2 { font-size:clamp(27px,3.4vh,43px); margin:3px 0 4px; }
  #faculty .faculty-layout { flex:1 1 0; min-height:0; width:100%; }
  #faculty .faculty-column { height:100%; min-height:0; padding:clamp(10px,1.5vh,18px); }
  #faculty .faculty-preview-note { flex:none; margin:clamp(7px,1.2vh,14px) 0 0; }
  #faculty .faculty-actions { flex:none; margin-top:clamp(7px,1.2vh,14px); }
  #faculty .faculty-actions button { padding:clamp(7px,1vh,12px) 18px; }
  #faculty .faculty-base-art { min-height:0; }
}
/* Translucent glass panels let the illustrated campus show through. */
#faculty .faculty-column {
  background:linear-gradient(150deg,rgba(17,49,117,.76),rgba(9,28,79,.70));
  border-color:rgba(116,190,255,.88);
  backdrop-filter:blur(5px) saturate(1.15);
  -webkit-backdrop-filter:blur(5px) saturate(1.15);
}
#faculty .info-faction { background:linear-gradient(135deg,rgba(37,81,165,.78),rgba(22,49,120,.75)); }
#faculty .info-hint { background:rgba(7,27,79,.66); }
#faculty .faculty-option { background:linear-gradient(180deg,rgba(44,83,170,.81),rgba(28,54,126,.79)); }
#faculty .faculty-option.selected { background:rgba(54,95,186,.86); }
